import { DailyClosing, FinancialFields } from "../types";
import { getSupabase, isSupabaseConfigured } from "./supabase";

const LOCAL_QUEUE_KEY = "mof-closings-queue";

export async function findExistingClosing(branchId: string, businessDate: string): Promise<DailyClosing | null> {
  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { data, error } = await supabase
        .from("daily_closings")
        .select("*")
        .eq("branch_id", branchId)
        .eq("business_date", businessDate)
        .maybeSingle();
      if (!error && data) {
        return normalizeRow(data);
      }
    } catch {}
  }
  // fallback to localStorage
  if (typeof window !== "undefined") {
    const list = readLocalQueue();
    return list.find(c => c.branchId === branchId && c.businessDate === businessDate) ?? null;
  }
  return null;
}

export async function saveClosing(c: DailyClosing): Promise<{ source: "supabase" | "local" }> {
  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { error } = await supabase.from("daily_closings").upsert({...});
      if (!error) return { source: "supabase" };
    } catch {}
  }
  if (typeof window !== "undefined") {
    const list = readLocalQueue();
    list.push(c);
    writeLocalQueue(list);
  }
  return { source: "local" };
}
