"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowRight, Calculator, Lock, Upload, ChevronLeft, Check, Plus, Home,
  AlertTriangle, Building2, Image as ImageIcon, X,
} from "lucide-react";
import { Branch, DailyClosing, EMPTY_FINANCIAL_FIELDS, FinancialFields, computeShortageOrExcess } from "../types";
import { loadBranches } from "../lib/branches";
import { findExistingClosing, saveClosing } from "../lib/closings";

const BRANCH_KEY = "mof-selected-branch";

type Step = 1 | 2 | 3;

interface FileSlot {
  file?: File;
  url?: string;
  name?: string;
}

export default function CashierPage() {
  const [branches, setBranches] = useState<Branch[]>([]);
  const [branch, setBranch] = useState<Branch | null>(null);
  const [isBranchLocked, setIsBranchLocked] = useState(false);
  const [showBranchConfirm, setShowBranchConfirm] = useState(false);

  const [step, setStep] = useState<Step>(1);
  const [businessDate, setBusinessDate] = useState<string>(() => new Date().toISOString().slice(0,10));
  const [zReport, setZReport] = useState<FileSlot>({});
  const [madaProof, setMadaProof] = useState<FileSlot>({});
  const [cashProof, setCashProof] = useState<FileSlot>({});
  const [visaProof, setVisaProof] = useState<FileSlot>({});
  const [manualActualCash, setManualActualCash] = useState<string>("");

  const [fields, setFields] = useState<FinancialFields>({ ...EMPTY_FINANCIAL_FIELDS });
  const [isSaving, setIsSaving] = useState(false);
  const [savedClosing, setSavedClosing] = useState<DailyClosing | null>(null);
  const [duplicate, setDuplicate] = useState<DailyClosing | null>(null);
  const [showDupConfirm, setShowDupConfirm] = useState(false);

  useEffect(() => {
    loadBranches().then(setBranches).catch(() => setBranches([]));
    try {
      const raw = localStorage.getItem(BRANCH_KEY);
      if (raw) {
        const b = JSON.parse(raw) as Branch;
        setBranch(b);
        setIsBranchLocked(true);
      }
    } catch {}
  }, []);

  const shortageOrExcess = useMemo(
    () => computeShortageOrExcess(fields.cashActualHanded, fields.cashSystem),
    [fields.cashActualHanded, fields.cashSystem]
  );

  function chooseBranch(b: Branch) {
    setBranch(b);
    setIsBranchLocked(true);
    localStorage.setItem(BRANCH_KEY, JSON.stringify(b));
  }

  function requestChangeBranch() {
    setShowBranchConfirm(true);
  }

  function confirmChangeBranch() {
    setShowBranchConfirm(false);
    setIsBranchLocked(false);
    localStorage.removeItem(BRANCH_KEY);
  }

  function onPickFile(slot: "z" | "mada" | "cash" | "visa", f?: File) {
    const next: FileSlot = f ? { file: f, url: URL.createObjectURL(f), name: f.name } : {};
    if (slot === "z") setZReport(next);
    else if (slot === "mada") setMadaProof(next);
    else if (slot === "cash") setCashProof(next);
    else setVisaProof(next);
  }

  function updateField<K extends keyof FinancialFields>(k: K, v: number) {
    setFields(prev => ({ ...prev, [k]: v }));
  }

  async function checkDup() {
    if (!branch) return;
    const existing = await findExistingClosing(branch.id, businessDate);
    setDuplicate(existing);
    if (existing) {
      setShowDupConfirm(true);
    } else {
      proceedToStep2();
    }
  }

  function proceedToStep2() {
    setStep(2);
  }

  function proceedToStep3() {
    // Merge shortageOrExcess
    const finalFields = { ...fields, shortageOrExcess };
    setFields(finalFields);
    setStep(3);
  }

  async function submit(override: boolean) {
    if (!branch || isSaving) return;
    setShowDupConfirm(false);
    setIsSaving(true);
    try {
      const now = new Date().toISOString();
      const id = `close-${Date.now()}`;
      const closing: DailyClosing = {
        id,
        branchId: branch.id,
        businessDate,
        status: "pending",
        zReportImageUrl: zReport.url,
        paymentProofImageUrls: [madaProof.url, cashProof.url, visaProof.url].filter(Boolean),
        reviewedData: { ...fields, shortageOrExcess },
        manualActualCash: manualActualCash ? Number(manualActualCash) : undefined,
        createdAt: now,
        updatedAt: now,
      };
      await saveClosing(closing, override);
      setSavedClosing(closing);
    } finally {
      setIsSaving(false);
    }
  }

  function newSubmission() {
    setStep(1);
    setSavedClosing(null);
    setFields({ ...EMPTY_FINANCIAL_FIELDS });
    setZReport({}); setMadaProof({}); setCashProof({}); setVisaProof({});
    setManualActualCash("");
    setDuplicate(null);
  }

  // ...render
}
