import { DailyClosing } from "../types";
import { getSupabase, isSupabaseConfigured } from "./supabase";

const LOCAL_QUEUE_KEY = "mof-closings-queue";

function readLocalQueue(): DailyClosing[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(LOCAL_QUEUE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as DailyClosing[]) : [];
  } catch {
    return [];
  }
}

function writeLocalQueue(list: DailyClosing[]): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(LOCAL_QUEUE_KEY, JSON.stringify(list));
  } catch {}
}

interface ClosingRow {
  id: string;
  branch_id: string;
  business_date: string;
  status: DailyClosing["status"];
  z_report_image_url?: string | null;
  payment_proof_image_urls?: string[] | null;
  ai_extracted_data?: unknown;
  ai_confidence?: unknown;
  reviewed_data?: unknown;
  manually_modified_fields?: string[] | null;
  manual_actual_cash?: number | null;
  auditor_id?: string | null;
  auditor_comment?: string | null;
  auditor_reviewed_at?: string | null;
  created_at?: string;
  updated_at?: string;
}

function rowToClosing(r: ClosingRow): DailyClosing {
  return {
    id: r.id,
    branchId: r.branch_id,
    businessDate: r.business_date,
    status: r.status,
    zReportImageUrl: r.z_report_image_url ?? undefined,
    paymentProofImageUrls: r.payment_proof_image_urls ?? undefined,
    aiExtractedData:
      (r.ai_extracted_data as DailyClosing["aiExtractedData"]) ?? undefined,
    aiConfidence:
      (r.ai_confidence as DailyClosing["aiConfidence"]) ?? undefined,
    reviewedData: (r.reviewed_data as DailyClosing["reviewedData"]) ?? undefined,
    manuallyModifiedFields:
      (r.manually_modified_fields as DailyClosing["manuallyModifiedFields"]) ??
      undefined,
    manualActualCash: r.manual_actual_cash ?? undefined,
    auditorId: r.auditor_id ?? undefined,
    auditorComment: r.auditor_comment ?? undefined,
    auditorReviewedAt: r.auditor_reviewed_at ?? undefined,
    createdAt: r.created_at ?? new Date().toISOString(),
    updatedAt: r.updated_at ?? new Date().toISOString(),
  };
}

function closingToRow(c: DailyClosing): ClosingRow {
  return {
    id: c.id,
    branch_id: c.branchId,
    business_date: c.businessDate,
    status: c.status,
    z_report_image_url: c.zReportImageUrl ?? null,
    payment_proof_image_urls: c.paymentProofImageUrls ?? [],
    ai_extracted_data: (c.aiExtractedData as unknown) ?? null,
    ai_confidence: (c.aiConfidence as unknown) ?? null,
    reviewed_data: (c.reviewedData as unknown) ?? null,
    manually_modified_fields: c.manuallyModifiedFields ?? [],
    manual_actual_cash: c.manualActualCash ?? null,
    auditor_id: c.auditorId ?? null,
    auditor_comment: c.auditorComment ?? null,
    auditor_reviewed_at: c.auditorReviewedAt ?? null,
    created_at: c.createdAt,
    updated_at: c.updatedAt,
  };
}

export async function findExistingClosing(
  branchId: string,
  businessDate: string,
): Promise<DailyClosing | null> {
  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { data, error } = await supabase
        .from("daily_closings")
        .select("*")
        .eq("branch_id", branchId)
        .eq("business_date", businessDate)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (!error && data) {
        return rowToClosing(data as ClosingRow);
      }
    } catch (e) {
      console.warn("[closings] supabase lookup failed", e);
    }
  }
  if (typeof window !== "undefined") {
    const list = readLocalQueue();
    return (
      list.find(
        (c) => c.branchId === branchId && c.businessDate === businessDate,
      ) ?? null
    );
  }
  return null;
}

export async function saveClosing(
  closing: DailyClosing,
  _override: boolean,
): Promise<{ source: "supabase" | "local" }> {
  if (isSupabaseConfigured) {
    try {
      const supabase = getSupabase();
      const { error } = await supabase
        .from("daily_closings")
        .upsert(closingToRow(closing), { onConflict: "branch_id,business_date" });
      if (!error) {
        return { source: "supabase" };
      }
      console.warn("[closings] supabase insert error", error.message);
    } catch (e) {
      console.warn("[closings] supabase insert threw", e);
    }
  }
  // Local fallback
  if (typeof window !== "undefined") {
    const list = readLocalQueue();
    const idx = list.findIndex(
      (c) => c.branchId === closing.branchId && c.businessDate === closing.businessDate,
    );
    if (idx >= 0) list[idx] = closing;
    else list.push(closing);
    writeLocalQueue(list);
  }
  return { source: "local" };
}
